prompt --application/shared_components/user_interface/templates/region/beam_frame
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(829339268576619163)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TBeamFrame #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <span class="amc-TBeamFrame-beam" aria-hidden="true"></span>',
'  <div class="amc-TBeamFrame-surface">',
'    <header class="amc-TBeamFrame-header">',
'      <span class="amc-TBeamFrame-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TBeamFrame-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TBeamFrame-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TBeamFrame-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TBeamFrame-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Beam Frame'
,p_internal_name=>'AMC_TPL_BEAM_FRAME'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-beam-frame.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with a travelling border beam. Title and icon come from the region; buttons in Help, Edit, Change, Copy, Delete and Create sit in the header, and Previous, Close and Next in the footer. Template options add a second beam, success or danger colors, a slower beam, no body padding or a visually hidden header. Under reduced motion the beam stops as a static gradient border; in forced-colors mode the frame becomes a plain system border.'
);
end;
